import {
  useQuery,
  useSuspenseQuery,
  useMutation,
  queryOptions,
  mutationOptions,
} from '@tanstack/preact-query'
import type {
  UseQueryOptions,
  UseSuspenseQueryOptions,
  UseMutationOptions,
  DefaultError,
  QueryClient,
} from '@tanstack/preact-query'
import type { ClientRequestOptions, InferRequestType } from 'hono/client'
import { parseResponse } from 'hono/client'
import { client } from '../client'

export function getV1Key() {
  return ['v1'] as const
}

export function getV2Key() {
  return ['v2'] as const
}

export function getV1FeaturesQueryKey(args: InferRequestType<typeof client.v1.features.$get>) {
  return ['v1', '/v1/features', args] as const
}

export function getV1FeaturesQueryOptions<
  TData = Awaited<
    ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.features.$get>>>>
  >,
  TError = DefaultError,
>(args: InferRequestType<typeof client.v1.features.$get>, options?: ClientRequestOptions) {
  return queryOptions<
    Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.features.$get>>>>>,
    TError,
    TData,
    ReturnType<typeof getV1FeaturesQueryKey>
  >({
    queryKey: getV1FeaturesQueryKey(args),
    queryFn({ signal }) {
      return parseResponse(
        client.v1.features.$get(args, { ...options, init: { ...options?.init, signal } }),
      )
    },
  })
}

export function useV1Features<
  TData = Awaited<
    ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.features.$get>>>>
  >,
  TError = DefaultError,
>(
  args: InferRequestType<typeof client.v1.features.$get>,
  options?: {
    query?: Omit<
      UseQueryOptions<
        Awaited<
          ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.features.$get>>>>
        >,
        TError,
        TData,
        ReturnType<typeof getV1FeaturesQueryKey>
      >,
      'queryKey' | 'queryFn'
    >
    options?: ClientRequestOptions
  },
  queryClient?: QueryClient,
) {
  const { query: queryOptions, options: clientOptions } = options ?? {}
  return useQuery(
    { ...getV1FeaturesQueryOptions<TData, TError>(args, clientOptions), ...queryOptions },
    queryClient,
  )
}

